-- Migration 0001: Tabel BOM (Bill of Materials) Produksi Makassar untuk Cloudflare D1
DROP TABLE IF EXISTS bom;
CREATE TABLE bom (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  varian_kue TEXT NOT NULL,
  bahan_baku TEXT NOT NULL,
  satuan TEXT NOT NULL,
  qty_per_box REAL NOT NULL DEFAULT 0,
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX idx_bom_bahan_baku ON bom(bahan_baku);
CREATE INDEX idx_bom_varian_kue ON bom(varian_kue);

